// Garde chaque commande dans la mémoire du workflow (pas de mail, pas de Google Sheet).
// Les commandes s'affichent dans l'Espace liste du site : onglet Boutique → Les commandes.
const store = $getWorkflowStaticData('global');
store.commandes = store.commandes || [];

const b = $input.first().json.body || {};
if (b.website) return [{ json: { ok: true } }]; // champ piège rempli : robot, on ignore sans rien enregistrer

const clean = (v, max = 300) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const items = String(b.items ?? '').split('\n').map((l) => clean(l, 120)).filter(Boolean).slice(0, 40);
const row = {
  id: clean(b.orderId, 30) || ('LQ-' + Date.now().toString(36).toUpperCase()),
  date: new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }),
  sentAt: new Date().toISOString(),
  name: clean(b.name, 120),
  email: clean(b.email, 160),
  phone: clean(b.phone, 40),
  where: clean(b.where, 200),
  when: clean(b.when, 120) || 'Dès que possible',
  articles: items.join(', '),
  count: clean(b.count, 4),
  notes: clean(b.notes, 1000),
  done: false,
};
if (!row.name || !row.where || !row.articles) return [{ json: { ok: false, error: 'incomplet' } }];
if (store.commandes.some((r) => r.id === row.id)) return [{ json: { ok: true, id: row.id, doublon: true } }];
if (store.commandes.length >= 5000) return [{ json: { ok: false, error: 'plein' } }];
store.commandes.push(row);
return [{ json: { ok: true, id: row.id } }];

// Espace liste → Boutique → Les commandes : lire la liste, cocher « Livrée », supprimer une ligne.
// ⚠️ Remplacez CHANGEZ-MOI par la MÊME clé secrète que dans le workflow des cotisations
// (celle collée dans le site : Espace liste → Cotisations → Connexion n8n).
const CLE_SECRETE = 'CHANGEZ-MOI';

const b = $input.first().json.body || {};
const okKey = CLE_SECRETE !== 'CHANGEZ-MOI' && CLE_SECRETE.length >= 16 && String(b.key || '') === CLE_SECRETE;
if (!okKey) return [{ json: { ok: false, error: 'cle' } }];

const store = $getWorkflowStaticData('global');
store.commandes = store.commandes || [];
const id = String(b.id || '');

switch (String(b.action || 'list')) {
  case 'set': {
    const row = store.commandes.find((r) => r.id === id);
    if (!row) return [{ json: { ok: false, error: 'introuvable' } }];
    row.done = b.value === 'Oui';
    return [{ json: { ok: true } }];
  }
  case 'delete': {
    const i = store.commandes.findIndex((r) => r.id === id);
    if (i < 0) return [{ json: { ok: false, error: 'introuvable' } }];
    store.commandes.splice(i, 1);
    return [{ json: { ok: true } }];
  }
  default:
    return [{ json: { ok: true, commandes: store.commandes } }];
}
